Two files below. Per your note, `state-rw` is imported and `run` writes its input to `last-input` on every call. The returned report is unchanged by that.

`notified` reports the actual result of `notify`. The contract needs it to be `true`, but the body can't force that. If the notifier returns `false`, the report will show `false`.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{heartbeat-report};

    import aap:caps/http-client@0.1.0;
    import aap:caps/notifier@0.1.0;
    import aap:caps/state-rw@0.1.0;
    import wasi:clocks/wall-clock@0.2.0;

    export run: func(feed-url: string) -> heartbeat-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input in the shared store (approved grant).
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat at {}s: fetched {} chars", seconds, fetched);
        let notified = notifier::notify(&message);

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

